// @ts-expect-error -- .open-next/worker.js is generated by `opennextjs-cloudflare build` and has no types.
import openNext from "./.open-next/worker.js";
// @ts-expect-error -- cloudflare:workers is provided by the Workers runtime.
import { WorkerEntrypoint } from "cloudflare:workers";
import { edgeCacheHeaders, hasRequestCredentials, imageCacheHeaders, imageFallbackUrl, isEdgeCacheableRequest, isImageRequest, isProductMove, isRscRequest, purgeEdgeCache, renderState } from "./src/lib/edge-cache";
import { withSecurityHeaders } from "./src/lib/security-headers";

type Handler = { fetch(request: Request, env: unknown, ctx: unknown): Promise<Response> };
type PublicCacheBinding = {
  fetch(request: Request): Promise<Response>;
  purge(): Promise<void>;
};
type GatewayContext = { exports: { PublicCache: PublicCacheBinding } };
const next = openNext as Handler;
const SENSITIVE_PATH = /^\/(?:admin(?:\/|$)|api(?:\/|$)|auth(?:\/|$))/;

/** Security headers on every response; a response without Cache-Control is never stored (V1-CACHE-01). */
function finalHeaders(source: Headers, forcePrivate = false): Headers {
  const headers = withSecurityHeaders(new Headers(source));
  if (forcePrivate || headers.has("set-cookie")) headers.set("Cache-Control", "private, no-store, max-age=0");
  else if (!headers.has("cache-control")) headers.set("Cache-Control", "private, no-store");
  return headers;
}

/** An old product URL is a 301 (Next can only emit 308 for permanentRedirect), and no cache keeps
 * it: the product may move again, and a remembered A→B would loop once B→A. */
function finalResponse(request: Request, response: Response, body: BodyInit | null, headers: Headers): Response {
  const moved = isProductMove(request, response);
  if (moved) headers.set("Cache-Control", "no-store");
  return new Response(body, { status: moved ? 301 : response.status, statusText: moved ? "Moved Permanently" : response.statusText, headers });
}

async function fetchPrivate(request: Request, env: unknown, ctx: unknown): Promise<Response> {
  const response = await next.fetch(request, env, ctx);
  const forcePrivate = hasRequestCredentials(request) || SENSITIVE_PATH.test(new URL(request.url).pathname);
  return finalResponse(request, response, response.body, finalHeaders(response.headers, forcePrivate));
}

async function fetchPublic(request: Request, env: unknown, ctx: unknown): Promise<Response> {
  if (!isEdgeCacheableRequest(request)) return fetchPrivate(request, env, ctx);
  const state = { degraded: false };
  return renderState.run(state, async () => {
    const response = await next.fetch(request, env, ctx);
    // Read the whole body first: rendering may still be fetching data after the headers exist,
    // and the degraded flag is only final once the page is complete.
    const body = await response.arrayBuffer();
    const cacheHeaders = isImageRequest(request) ? imageCacheHeaders(response) : edgeCacheHeaders(response, state.degraded, isRscRequest(request));
    return finalResponse(request, response, request.method === "HEAD" ? null : body,
      cacheHeaders ? finalHeaders(cacheHeaders) : finalHeaders(response.headers, true));
  });
}

/** A transform that throws or times out (Images 9523, upstream 504) sends the browser to the original upload
 * instead of breaking the image. */
async function fetchImage(request: Request, env: unknown, ctx: GatewayContext): Promise<Response> {
  const fallback = imageFallbackUrl(request);
  try {
    const response = await (isEdgeCacheableRequest(request) ? ctx.exports.PublicCache.fetch(request) : fetchPrivate(request, env, ctx));
    if (response.status < 500 || !fallback) return response;
    console.warn("image transform failed, serving original", response.status, fallback);
  } catch (error) {
    if (!fallback) throw error;
    console.warn("image transform failed, serving original", String(error), fallback);
  }
  return new Response(null, { status: 302, headers: finalHeaders(new Headers({ Location: fallback }), true) });
}

/** Only this inner entrypoint has Workers Cache enabled. The public gateway never sends credentials here. */
export class PublicCache extends WorkerEntrypoint {
  declare env: unknown;
  declare ctx: unknown;

  async fetch(request: Request): Promise<Response> {
    if (!isImageRequest(request)) return fetchPublic(request, this.env, this.ctx);
    // A failed transform is an uncached 502 here, so the gateway falls back without an uncaught exception.
    return fetchPublic(request, this.env, this.ctx).catch((error: unknown) => {
      console.warn("image transform failed", String(error));
      return new Response(null, { status: 502, headers: finalHeaders(new Headers(), true) });
    });
  }

  /** Custom RPC bypasses the HTTP cache and purges the cache owned by this entrypoint. */
  async purge(): Promise<void> {
    if (await purgeEdgeCache(this.ctx)) return;
    // Local workerd (wrangler dev) has no ctx.cache, so there is nothing to purge. Only the CI e2e job sets this,
    // through apps/web/.dev.vars (ignored, never uploaded by wrangler deploy); production keeps failing closed.
    const localOnly = (this.env as { E2E_LOCAL_NO_EDGE_CACHE?: string } | undefined)?.E2E_LOCAL_NO_EDGE_CACHE === "1";
    if (localOnly && !(this.ctx as { cache?: unknown } | undefined)?.cache) return;
    throw new Error("Workers Cache API unavailable");
  }
}

/** The default entrypoint is uncached, so credentials are checked before any public-cache lookup. */
const worker = {
  async fetch(request: Request, env: unknown, ctx: GatewayContext): Promise<Response> {
    const url = new URL(request.url);
    if (request.method === "POST" && url.pathname === "/api/revalidate") {
      const response = await fetchPrivate(request, env, ctx);
      if (!response.ok) return response;
      try {
        await ctx.exports.PublicCache.purge();
      } catch {
        return new Response(JSON.stringify({ error: "Edge cache purge failed" }), {
          status: 502,
          headers: finalHeaders(new Headers({ "Content-Type": "application/json" }), true),
        });
      }
      return response;
    }
    if (isImageRequest(request)) return fetchImage(request, env, ctx);
    if (hasRequestCredentials(request)) return fetchPrivate(request, env, ctx);
    if (isEdgeCacheableRequest(request)) return ctx.exports.PublicCache.fetch(request);
    return fetchPrivate(request, env, ctx);
  },
};

export default worker;
